entries[12754] = { ["name"] = "The Big One", ["text"] = "12.5 sec cast\nTools: Blacksmith Hammer , Arclight Spanner\nReagents:\nMithril Casing , Goblin Rocket Fuel , Solid Dynamite (6), Unstable Trigger\n(2)\nRequires Engineering\n(225)\n\nUse: Inflicts 340 to 460 Fire damage and incapacitates targets for 5 sec in a 10 yard radius. Any damage will break the effect. Unreliable against targets higher than level 60. (1 Min Cooldown)" }
entries[12755] = { ["name"] = "Goblin Bomb Dispenser", ["text"] = "12.5 sec cast\nTools: Blacksmith Hammer , Arclight Spanner\nReagents:\nMithril Casing (2), Solid Blasting Powder (4), Truesilver Bar (6), Unstable Trigger , Accurate Scope (2)\nBinds when picked up\nTrinket\nRequires Engineering\n(230)\nUse: Creates a mobile bomb that charges the nearest enemy and explodes for 315 to 385 fire damage. (30 Min Cooldown)" }
entries[12758] = { ["name"] = "Goblin Rocket Helmet", ["text"] = "12.5 sec cast\nTools: Blacksmith Hammer , Arclight Spanner\nReagents:\nGoblin Construction Helmet , Goblin Rocket Fuel (4), Mithril Bar (4), Unstable Trigger\nGoblin Rocket Helmet\nBinds when equipped\nHead Cloth\n50 Armor\n+15 Stamina\nDurability 45 / 45\nRequires Engineering\n(235)\nUse: Charge an enemy, knocking it silly for 30 seconds. Also knocks you down, stunning you for a short period of time. Any damage caused will revive the target. Chance to fizzle when used against targets over level 60. (20 Min Cooldown)" }
entries[12759] = { ["name"] = "Gnomish Death Ray", ["text"] = "12.5 sec cast\nTools: Blacksmith Hammer , Arclight Spanner\nReagents:\nMithril Tube (2), Unstable Trigger , Essence of Undeath , Ichor of Undeath (4), Inlaid Mithril Cylinder\nBinds when picked up\nTrinket\nUse: The device charges over time using your life force and then directs a burst of energy at your opponent. (5 Min Cooldown)\n\"Death or Serious Injury may result from use of this device.\"" }
entries[12760] = { ["name"] = "Goblin Sapper Charge", ["text"] = "25 sec cast\nReagents:\nMageweave Cloth , Solid Blasting Powder (3), Unstable Trigger\nRequires Engineering\n(205)\n\nUse: Explodes when triggered dealing 450 to 750 Fire damage to all enemies nearby and 375 to 625 damage to you. (5 Min Cooldown)" }
